CREATE TEMPORARY VIEW dws_search_metrics_${grass_region_without_quote} AS
SELECT
    user_id
    ,search_session_id
    ,MAX(voice_session_id) AS voice_session_id
    ,MAX(request_id) AS request_id
    ,SUM(IF(operation = 'click', operation_cnt, NULL)) AS click_cnt
    ,SUM(IF(operation = 'impression', operation_cnt, NULL)) AS imp_cnt
    ,SUM(IF(operation = 'order', operation_cnt, NULL)) AS order_cnt
    ,SUM(IF(operation = 'order', gmv, NULL)) AS gmv
FROM
    dwd_search_metrics_${grass_region_without_quote}
WHERE
    request_id IS NOT NULL
GROUP BY
    1,2;

--sql_divide_splitter--

CREATE TEMPORARY VIEW ods_query_service_${grass_region_without_quote} AS
SELECT
    COALESCE(GET_JSON_OBJECT(value, '$.requestID'), 'NULL') AS request_id
    ,MAX(CASE
        WHEN GET_JSON_OBJECT(value, '$.kids_voice_search') IS NOT NULL THEN TRUE
        ELSE FALSE
    END) AS is_kid
    ,MAX(GET_JSON_OBJECT(value, '$.kids_voice_search.ori_keyword')) AS ori_keyword
    ,MAX(GET_JSON_OBJECT(value, '$.kids_voice_search.mod_keyword')) AS mod_keyword
FROM
    search_data.ods_query_service_analysis_log_1h_raw
WHERE
    country = ${grass_region}
    AND dt BETWEEN ${local_date} AND date_add(${local_date}, 1)
    AND date(date_timezone_convert(dt,hh,'SG',country,"yyyy-MM-dd")) = ${local_date}
GROUP BY
    1;

--sql_divide_splitter--

CREATE TEMPORARY VIEW llm_voice_search_raw_${grass_region_without_quote} AS
SELECT
    REPLACE(TRIM(BOTH '"' FROM request), '\\"', '"') AS request -- To make it json extractable
    ,response
FROM
    llm_algo.compass_voice_search_scheduled
WHERE
    dt BETWEEN DATE_SUB(${local_date}, 1) AND DATE_ADD(${local_date}, 1);
    -- Take 1 day before to accomodate nonasian regions local_date, 1 day after to accomodate ID 23rd hour
    -- dt here is regional_date instead of local_date

--sql_divide_splitter--

CREATE TEMPORARY VIEW llm_voice_search_json_cols_${grass_region_without_quote} AS
SELECT
    GET_JSON_OBJECT(request, '$.session_id') AS voice_session_id
    ,GET_JSON_OBJECT(request, '$.chunk_id') AS chunk_id
    ,GET_JSON_OBJECT(request, '$.download_url') AS audio_url
    ,GET_JSON_OBJECT(request,'$.classification') AS classification
    ,CASE
        WHEN GET_JSON_OBJECT(request,'$.is_realTime') IN ('true', '1') THEN TRUE
        ELSE FALSE
    END AS is_realtime
    ,CASE
        WHEN GET_JSON_OBJECT(request,'$.finished') IN ('true','1') THEN TRUE
        ELSE FALSE
    END AS finished
    ,response
FROM
    llm_voice_search_raw_${grass_region_without_quote}
WHERE
    GET_JSON_OBJECT(request, '$.session_id') != '';

--sql_divide_splitter--

CREATE TEMPORARY VIEW llm_voice_search_realtime_${grass_region_without_quote} AS
SELECT
    voice_session_id
    ,audio_url
    ,response
    ,classification
    ,is_realtime
    ,ROW_NUMBER() OVER (PARTITION BY voice_session_id ORDER BY chunk_id ASC) AS chunk_id_rank
    -- For realtime, only smallest chunk_id has audio for each voice_session_id
FROM
    llm_voice_search_json_cols_${grass_region_without_quote}
WHERE
    is_realtime = TRUE
    AND finished = TRUE;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_llm_voice_search_${grass_region_without_quote} AS
SELECT
    voice_session_id
    ,audio_url
    ,response
    ,classification
    ,is_realtime
FROM
    llm_voice_search_json_cols_${grass_region_without_quote}
WHERE
    is_realtime = FALSE
UNION ALL
SELECT
    voice_session_id
    ,audio_url
    ,response
    ,classification
    ,is_realtime
FROM
    llm_voice_search_realtime_${grass_region_without_quote}
WHERE
    chunk_id_rank = 1;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dwd_status_code_info_${grass_region_without_quote} AS
SELECT
    voice_search_session_id AS voice_session_id
    ,MAX(fe_status_code_info) AS status_code_info
    ,MAX(TRANSFORM(fe_status_code_info, x -> FROM_JSON(x, 'STRUCT<status_code:STRING,timestamp:BIGINT,chunk_id:BIGINT,interval:BIGINT,recog_result:STRING,finished:STRING>'))) AS status_code_struct
    ,MAX(use_mobile_vad) AS use_mobile_vad
    ,MAX(is_manual_stop) AS is_manual_stop
FROM
    srdi_mart.dwd_sr_data_warehouse_platform
WHERE
    grass_region = ${grass_region}
    AND local_date = ${local_date}
    AND operation = 'click'
    AND original_operation = 'action_voice_search'
    AND page_type = 'pre_search'
    AND SIZE(fe_status_code_info) > 0
GROUP BY
    1;

--sql_divide_splitter--

CREATE TEMPORARY VIEW status_code_info_explode_${grass_region_without_quote} AS
SELECT
    voice_session_id
    ,use_mobile_vad
    ,status_code_detail.status_code
    ,status_code_detail.timestamp AS timestamp
    ,status_code_detail.chunk_id
    ,status_code_detail.interval
    ,status_code_detail.recog_result
    ,status_code_detail.finished
FROM
    dwd_status_code_info_${grass_region_without_quote}
LATERAL VIEW
    EXPLODE(status_code_struct) AS status_code_detail;

--sql_divide_splitter--

CREATE TEMPORARY VIEW status_code_next_timestamp_${grass_region_without_quote} AS
SELECT
    voice_session_id
    ,timestamp
    ,LEAD(timestamp) OVER (PARTITION BY voice_session_id ORDER BY timestamp ASC) AS next_timestamp
FROM
    status_code_info_explode_${grass_region_without_quote};

--sql_divide_splitter--

CREATE TEMPORARY VIEW status_code_avg_delay_time_${grass_region_without_quote} AS
SELECT
    voice_session_id
    ,AVG(next_timestamp - timestamp) AS delay_time
FROM
    status_code_next_timestamp_${grass_region_without_quote}
GROUP BY
    1;

--sql_divide_splitter--

CREATE TEMPORARY VIEW status_code_final_recog_result_${grass_region_without_quote} AS
SELECT
    voice_session_id
    ,recog_result
    ,timestamp
FROM
    status_code_info_explode_${grass_region_without_quote}
WHERE
    status_code = 200
    AND use_mobile_vad iS NULL
UNION ALL
SELECT
    voice_session_id
    ,recog_result
    ,timestamp
FROM 
    (
        SELECT
            voice_session_id
            ,recog_result
            ,timestamp
            ,row_number() OVER (PARTITION BY voice_session_id order by timestamp DESC) as rank_num
        FROM
            status_code_info_explode_${grass_region_without_quote}
        WHERE
            status_code = 9002
            AND use_mobile_vad iS NOT NULL
            AND finished = 'true'
    )
WHERE 
    rank_num = 1;

--sql_divide_splitter--

CREATE TEMPORARY VIEW status_code_wait_time_${grass_region_without_quote} AS
SELECT
    a.voice_session_id
    ,MAX(b.timestamp) - MIN(a.timestamp) AS wait_time
FROM
    status_code_info_explode_${grass_region_without_quote} a
JOIN
    status_code_final_recog_result_${grass_region_without_quote} b
ON
    a.voice_session_id = b.voice_session_id
    AND a.recog_result = b.recog_result
WHERE
    a.use_mobile_vad IS NULL
    OR (
        a.use_mobile_vad IS NOT NULL
        AND a.finished = 'false'
    )
GROUP BY
    1;

--sql_divide_splitter--

