CREATE TEMPORARY VIEW mpi_voice_search_${grass_region_without_quote} AS
SELECT
    trace_id AS voice_session_id
    ,audio_url
    ,GET_JSON_OBJECT(response,'$.text') AS llm_response
    ,GET_JSON_OBJECT(request, '$.language') AS language
    ,GET_JSON_OBJECT(request, '$.segments') AS segments
    ,CAST(GET_JSON_OBJECT(response, '$.labels.classification') AS INT) AS mpi_classification
