INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_voice_search_session_level_metrics_1d
PARTITION (
    grass_region = ${grass_region}
    ,local_date = ${local_date}
)
SELECT
    a.voice_session_id AS voice_session_id
    ,COALESCE(a.search_session_id, f.search_session_id) AS search_session_id
    ,a.request_id AS request_id
    ,b.is_kid AS is_kid
    ,ori_keyword
    ,mod_keyword
    ,a.user_id AS user_id
    ,imp_cnt
    ,click_cnt
    ,order_cnt
    ,gmv
    ,COALESCE(c.audio_url, h.audio_url) AS audio_url
    ,COALESCE(c.response, h.llm_response) AS llm_response
    ,classification AS llm_classification
    ,is_realtime AS llm_is_realtime
    ,wait_time
    ,status_code_info
    ,no_result_cnt
    ,CASE
        WHEN a.voice_session_id = c.voice_session_id AND a.voice_session_id = h.voice_session_id THEN 'BOTH'
        WHEN a.voice_session_id = c.voice_session_id THEN 'LLM'
        WHEN a.voice_session_id = h.voice_session_id THEN 'MPI'
        ELSE NULL
    END AS model_source
    ,g.use_mobile_vad
    ,language
    ,segments
    ,is_manual_stop
    ,delay_time
    ,1.0 * voice_window_click_cnt / voice_window_imp_cnt AS voice_window_ctr
    ,fe_classification
    ,mpi_classification
FROM
    dws_search_metrics_${grass_region_without_quote} a
LEFT JOIN
    ods_query_service_${grass_region_without_quote} b
ON
    a.request_id = b.request_id
LEFT JOIN
    dws_llm_voice_search_${grass_region_without_quote} c
ON
    a.voice_session_id = c.voice_session_id
LEFT JOIN
    dwd_status_code_info_${grass_region_without_quote} d
ON
    a.voice_session_id = d.voice_session_id
LEFT JOIN
    status_code_wait_time_${grass_region_without_quote} e
ON
    a.voice_session_id = e.voice_session_id
FULL JOIN
    no_result_cnt_${grass_region_without_quote} f
ON
    a.search_session_id = f.search_session_id
LEFT JOIN
    use_mobile_vad_link_${grass_region_without_quote} g
ON
    a.voice_session_id = g.voice_session_id
LEFT JOIN
    mpi_voice_search_${grass_region_without_quote} h
ON
    a.voice_session_id = h.voice_session_id
LEFT JOIN
    status_code_avg_delay_time_${grass_region_without_quote} i
ON
    a.voice_session_id = i.voice_session_id
LEFT JOIN
    voice_window_click_${grass_region_without_quote} j
ON
    a.user_id = j.user_id
LEFT JOIN
    voice_window_impression_${grass_region_without_quote} k
ON
    a.user_id = k.user_id
LEFT JOIN
    fe_classification_${grass_region_without_quote} l
ON
    a.voice_session_id = l.voice_session_id;
